<?php
$menuItems=le_menu_config();$revision=le_menu_revision($menuItems);$editing=null;
foreach($menuItems as $item)if(($item['id']??'')===($_GET['edit_menu']??''))$editing=$item;
$form=$editing??['id'=>'','label'=>'','type'=>'url','target'=>'','order'=>count($menuItems),'enabled'=>true,'new_tab'=>false];
$menuPages=db()->query('SELECT id,title FROM pages ORDER BY title')->fetchAll();$menuPlugins=[];
foreach(db()->query('SELECT * FROM plugins WHERE enabled=1 ORDER BY name')->fetchAll() as $plugin)if(le_menu_public_file($plugin))$menuPlugins[]=$plugin;
?>
<div class="two-panel"><section class="panel"><h2><?=e(le_text('Menu witryny'))?></h2><p><?=e(le_text('Pozycje są wspólne dla menu na komputerze i telefonie.'))?></p><div class="role-list">
<?php foreach($menuItems as $item):$url=le_menu_target($item);?><div class="role-item"><div class="role-info"><strong><?=e(!empty($item['builtin'])?le_text($item['label']):$item['label'])?></strong><small><?=e((string)($url??le_text('Cel niedostępny')))?> · <?=e((string)$item['order'])?> · <?=e(le_text(!empty($item['enabled'])?'Widoczny':'Ukryty'))?></small></div><div class="actions"><a class="btn" href="<?=e(admin_url('menu',['edit_menu'=>$item['id']]))?>"><?=e(le_text('Edytuj'))?></a><form method="post" onsubmit="return confirm(<?=e(json_encode(le_text('Usunąć pozycję menu?')))?>)"><?=csrf_field()?><input type="hidden" name="action" value="menu_delete"><input type="hidden" name="menu_id" value="<?=e($item['id'])?>"><input type="hidden" name="menu_revision" value="<?=e($revision)?>"><button class="btn danger"><?=e(le_text('Usuń'))?></button></form></div></div><?php endforeach;?></div><a class="btn" href="<?=e(admin_url('menu'))?>"><?=e(le_text('Dodaj menu'))?></a></section>
<section class="panel"><h2><?=e(le_text($editing?'Edytuj menu':'Dodaj menu'))?></h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="menu_save"><input type="hidden" name="menu_id" value="<?=e($form['id'])?>"><input type="hidden" name="menu_revision" value="<?=e($revision)?>">
<label><?=e(le_text('Nazwa'))?><input class="input" name="label" maxlength="80" required value="<?=e($form['label'])?>"></label>
<label><?=e(le_text('Przekierowanie'))?><select class="input" name="target_type" data-menu-type><?php foreach(['url'=>'Adres URL','page'=>le_text('Podstrona'),'plugin'=>'Plugin'] as $value=>$label):?><option value="<?=$value?>" <?=$form['type']===$value?'selected':''?>><?=e(le_text($label))?></option><?php endforeach;?></select></label>
<label data-menu-target="url"><?=e(le_text('Adres URL'))?><input class="input" name="target_url" value="<?=e($form['type']==='url'?(string)$form['target']:'')?>" placeholder="<?=e(le_text('/galeria/ lub https://example.com'))?>"></label>
<label data-menu-target="page"><?=e(le_text('Podstrona'))?><select class="input" name="target_page"><option value=""><?=e(le_text('Wybierz podstronę'))?></option><?php foreach($menuPages as $page):?><option value="<?=(int)$page['id']?>" <?=$form['type']==='page'&&(int)$form['target']===(int)$page['id']?'selected':''?>><?=e($page['title'])?></option><?php endforeach;?></select></label>
<label data-menu-target="plugin"><?=e(le_text('Plugin'))?><select class="input" name="target_plugin"><option value=""><?=e(le_text('Wybierz plugin'))?></option><?php foreach($menuPlugins as $plugin):?><option value="<?=e($plugin['plugin_key'])?>" <?=$form['type']==='plugin'&&$form['target']===$plugin['plugin_key']?'selected':''?>><?=e($plugin['name'])?></option><?php endforeach;?></select><small><?=e(le_text('Lista pokazuje aktywne pluginy ze stroną publiczną.'))?></small></label>
<label><?=e(le_text('Kolejność'))?><input class="input" name="menu_order" type="number" value="<?=(int)$form['order']?>"></label>
<label class="check"><input type="checkbox" name="enabled" value="1" <?=!empty($form['enabled'])?'checked':''?>> <?=e(le_text('Widoczny w menu'))?></label><label class="check"><input type="checkbox" name="new_tab" value="1" <?=!empty($form['new_tab'])?'checked':''?>> <?=e(le_text('Otwórz w nowej karcie'))?></label>
<button class="btn primary"><?=e(le_text('Zapisz menu'))?></button></form></section></div>
